import sys
from math import comb

MOD = 10**9 + 7

def count_arrangements(N, K):
    results = [0] * K
    for i in range(1, K + 1):
        for j in range(i):
            results[i - 1] += comb(K, j) * comb(N - K, i - j - 1)
            results[i - 1] %= MOD
    return results

